// The configurations a function builds, and one written through the
// module's exports after it is set.
function makeConfigs() {
  const configs = {};
  configs.browser = { globals: { ky: 'readonly' } };
  return configs;
}

module.exports = {
  rules: {},
  configs: makeConfigs(),
};

module.exports.configs.forms = { globals: { superagent: 'readonly' } };
